"""Complete the original 40-question solid-tumor chapter."""
from create_oncology_gi_gu_skin import rows,q,ref
from qbank_authoring import finalize
TH=ref('NCI thyroid cancer professional summary','https://www.cancer.gov/types/thyroid/hp/thyroid-treatment-pdq')

q('A thyroid malignancy is composed of parafollicular C cells and produces calcitonin. Which classification is most likely?', 'Medullary thyroid carcinoma',[
 ('Papillary thyroid carcinoma','This is follicular-cell derived, with characteristic nuclear morphology.'),('Follicular thyroid carcinoma','This is follicular-cell derived; invasion establishes malignancy.'),('Primary thyroid lymphoma','This is a lymphoid tumor rather than a calcitonin-producing C-cell tumor.')],
 'Cell of origin predicts the marker and treatment pathway','**Medullary carcinoma is a C-cell neuroendocrine malignancy.**',['Calcitonin and CEA assist assessment and follow-up.','Evaluate hereditary RET-associated disease even without an obvious family history.'],'**Assess cervical extent and the hereditary endocrine context.**',['Radioiodine is not an effective C-cell-directed treatment.','Exclude associated pheochromocytoma before relevant surgery in hereditary disease.'],[['Medullary','C cells; calcitonin'],['Differentiated thyroid cancer','Follicular-cell origin'],['Hereditary assessment','RET/MEN2']],[TH],style='clinical_scenario')

q('Why can thyroid fine-needle aspiration reported as a follicular neoplasm fail to distinguish follicular adenoma from carcinoma?', 'The distinction requires assessment of capsular or vascular invasion in an adequately sampled tissue specimen',[
 ('Carcinoma is defined solely by the diameter of the nodule','Size informs risk but is not the defining adenoma–carcinoma distinction.'),('Any microfollicular cytological pattern proves carcinoma','Microfollicular architecture also occurs in adenomas.'),('Serum thyroglobulin reliably separates the two before surgery','It is not a specific discriminator in a patient with an intact thyroid.')],
 'Cytology cannot examine the whole tumor boundary','**Invasion establishes follicular carcinoma.**',['Nuclear features suggesting papillary carcinoma raise a different classification question.','Molecular testing can modify risk estimates without making every indeterminate lesion malignant.'],'**Choose management through the thyroid-nodule risk pathway.**',['Integrate ultrasound, cytology, molecular findings and patient factors.','Histological sampling must adequately assess the capsule and vessels.'],[['FNA','Samples cells'],['Histology','Assesses invasion'],['Size','Risk feature, not proof']],[TH])

q('An older patient develops a rapidly enlarging hard thyroid mass, dysphagia and stridor over several weeks. Which diagnosis is a major concern?', 'Anaplastic thyroid carcinoma',[
 ('A stable autonomous thyroid adenoma','This is not the typical explanation for rapidly progressive invasive airway symptoms.'),('A small incidental papillary microcarcinoma','Such lesions usually have a very different clinical tempo.'),('Subacute painful thyroiditis without further assessment','Inflammation is a differential, but this invasive presentation requires urgent cancer assessment.')],
 'Tempo and airway compromise make this urgent','**Anaplastic thyroid cancer is an aggressive undifferentiated malignancy.**',['Thyroid lymphoma is another important rapidly enlarging-mass differential.','Tissue diagnosis and actionable molecular assessment should be coordinated promptly.'],'**Secure urgent specialist airway assessment while establishing diagnosis.**',['Do not delay airway care for a complete elective staging sequence.','Treatment depends on resectability, molecular findings, fitness and goals.'],[['Tempo','Rapid enlargement'],['Threat','Airway compromise'],['Diagnosis','Urgent tissue and staging']],[TH],style='clinical_scenario')

q('Which statement best distinguishes differentiation, proliferation grade and hormonal function in gastroenteropancreatic neuroendocrine neoplasms?', 'A well-differentiated tumor can be nonfunctional, and proliferative grade is assessed separately using mitoses and Ki-67',[
 ('Absence of a hormone syndrome establishes a benign tumor','Nonfunctional tumors can be malignant and metastatic.'),('Any high Ki-67 automatically makes the morphology poorly differentiated','Well-differentiated grade 3 NETs exist and differ from poorly differentiated NEC.'),('Chromogranin positivity alone determines the exact grade','Grade requires site-appropriate proliferation assessment, not one lineage marker.')],
 'Three different biological axes must be described','**Morphological differentiation, proliferation and function are related but distinct.**',['Site-specific grading rules matter.','A clinically functional syndrome requires hormone effects, not staining alone.'],'**Use an integrated pathology and clinical classification.**',['Treatment differs between well-differentiated NET and poorly differentiated NEC.','Do not apply gastrointestinal Ki-67 rules indiscriminately to every organ.'],[['Differentiation','Morphology'],['Grade','Proliferation'],['Function','Clinical hormone syndrome']],[ref('NCI pancreatic neuroendocrine tumors professional summary','https://www.cancer.gov/types/pancreatic/hp/pnet-treatment-pdq')])

q('An adrenal mass is being considered for percutaneous biopsy in a patient with episodic headache, sweating and hypertension. What must be addressed first?', 'Evaluate for catecholamine secretion and avoid unprepared biopsy of a possible pheochromocytoma',[
 ('Use a normal serum cortisol to exclude pheochromocytoma','Cortisol evaluates a different adrenal hormone pathway.'),('Perform biopsy first because symptoms cannot indicate a functional lesion','Manipulation can precipitate a dangerous catecholamine crisis.'),('Use FDG avidity alone to establish a nonfunctional metastasis','Avidity does not exclude pheochromocytoma or prove metastatic origin.')],
 'The procedure can provoke the physiological emergency','**Plasma free or urinary fractionated metanephrines are standard initial biochemical tests.**',['Sampling conditions and medications influence interpretation.','Not every adrenal mass requires biopsy even after functional assessment.'],'**Coordinate endocrine and procedural review before intervention.**',['Assess whether tissue would change management.','Functional lesions require specialist preparation and treatment.'],[['First concern','Catecholamine secretion'],['Initial testing','Appropriate metanephrines'],['Biopsy','Selected only after safety assessment']],[ref('Endocrine Society PPGL guideline','https://academic.oup.com/jcem/article/99/6/1915/2537399')],style='clinical_scenario')

q('A deep enlarging thigh mass is suspicious for sarcoma. Which diagnostic strategy best protects subsequent definitive treatment?', 'Refer to a sarcoma team for imaging and a planned core biopsy with an appropriate tract',[
 ('Perform an unplanned local excision through whichever incision is convenient','This may contaminate tissue planes and compromise definitive surgery.'),('Begin systemic treatment from MRI appearance without pathological classification','Histological subtype and grade influence treatment.'),('Wait for ulceration before obtaining tissue','Progressive deep masses warrant timely assessment.')],
 'The diagnostic incision is part of the oncological plan','**Biopsy planning should be coordinated with the team providing definitive treatment.**',['The tract should be positioned to permit appropriate management during surgery.','Expert pathology is valuable because sarcoma subtypes differ substantially.'],'**Image before biopsy when feasible and avoid unplanned excision.**',['Choose the biopsy target and route carefully.','Discuss staging and limb-preserving options in a specialist multidisciplinary setting.'],[['Imaging','Defines anatomy'],['Core biopsy','Planned tract'],['Definitive surgery','Avoid contaminated planes']],[ref('ESMO sarcoma clinical practice guideline','https://www.annalsofoncology.org/article/S0923-7534%2821%2902184-0/fulltext')],style='clinical_scenario')

q('A metastatic carcinoma remains without an identified primary after initial evaluation. Which next approach is most appropriate?', 'Use morphology, a focused immunohistochemical panel, clinical pattern and indicated molecular tests to guide further evaluation',[
 ('Order every available tumor marker as an equally specific primary-site test','Most serum markers lack that specificity and can create misleading leads.'),('Assign the primary solely to the organ containing the largest metastasis','Metastatic burden need not identify the organ of origin.'),('Call the disease nonmalignant because the primary is not seen','Tissue-confirmed metastatic malignancy remains cancer despite an occult primary.')],
 'Unknown primary is a structured diagnostic category','**Classification begins with reliable tissue and lineage assessment.**',['Recognize specific treatable patterns and exclude important mimics.','Molecular findings can sometimes guide treatment even when anatomy remains uncertain.'],'**Select further tests for their likelihood of changing management.**',['Avoid exhaustive low-yield investigations without a clinical rationale.','Consider fitness, symptoms and goals while the work-up proceeds.'],[['Pathology','Lineage and phenotype'],['Clinical pattern','Directs focused investigation'],['Molecular testing','Potential therapeutic implications']],[ref('NCI cancer of unknown primary professional summary','https://www.cancer.gov/types/unknown-primary/hp/unknown-primary-treatment-pdq')],style='clinical_scenario')

q('Which viral association is most characteristic of a substantial subset of oropharyngeal squamous-cell carcinomas?', 'High-risk human papillomavirus',[
 ('Epstein–Barr virus as the defining association for this subset','EBV is more characteristic of nonkeratinizing nasopharyngeal carcinoma.'),('Hepatitis B virus','Its major oncological association is hepatocellular carcinoma.'),('Human herpesvirus 8','This is associated with Kaposi sarcoma and selected lymphoid disorders.')],
 'The anatomical site determines interpretation of viral markers','**HPV-associated oropharyngeal cancer is a biologically distinct group.**',['p16 immunohistochemistry is a validated surrogate in specified oropharyngeal settings.','p16 expression is not equivalent to HPV causation in every tumor and organ.'],'**Use site-appropriate pathological testing and staging.**',['Do not automatically transfer an oropharyngeal rule to oral-cavity cancer.','Risk-factor counseling remains relevant.'],[['Oropharynx subset','High-risk HPV'],['Nasopharynx subset','EBV'],['p16','Context-dependent surrogate']],[ref('ASCO endorsement of CAP head-and-neck HPV testing guidance','https://ascopubs.org/doi/10.1200/JOP.18.00433')])

q('A postmenopausal woman has persistent abdominal distension, ascites and a complex adnexal mass. What is the best interpretation of CA-125 testing?', 'It can support risk assessment in this symptomatic context but cannot independently confirm or exclude ovarian cancer',[
 ('An elevated CA-125 establishes ovarian cancer without tissue or further assessment','Benign serosal disease and other cancers can elevate it.'),('A normal CA-125 excludes all early ovarian malignancy','Sensitivity varies by stage and histological subtype.'),('Its role in a symptomatic mass proves benefit for routine average-risk population screening','Diagnostic assessment and population screening are different questions.')],
 'A marker is interpreted within the presenting probability','**The mass and clinical findings warrant a gynecological oncology pathway.**',['Ultrasound morphology and other investigations contribute to risk assessment.','CA-125 is neither cancer-specific nor uniformly elevated.'],'**Obtain appropriate specialist evaluation and staging.**',['Do not delay assessment because the marker is normal.','Do not infer that a diagnostic adjunct is an effective screening program.'],[['Symptomatic mass','Diagnostic evaluation'],['CA-125','Contextual adjunct'],['Average-risk screening','Different evidence requirement']],[ref('NCI ovarian epithelial cancer professional summary','https://www.cancer.gov/types/ovarian/hp/ovarian-epithelial-treatment-pdq'),ref('NCI ovarian screening professional summary','https://www.cancer.gov/types/ovarian/hp/ovarian-screening-pdq')],style='clinical_scenario')

q('Which feature is characteristic of uveal melanoma compared with common cutaneous melanoma?', 'Frequent GNAQ/GNA11 pathway alterations and a distinct molecular and metastatic profile',[
 ('BRAF V600 mutation is the defining alteration in nearly all cases','That is not the characteristic uveal molecular pattern.'),('Its biology and systemic treatment selection are interchangeable with cutaneous melanoma','Uveal melanoma is a distinct disease requiring its own evidence base.'),('An ocular primary cannot produce liver metastases','The liver is a major metastatic site in uveal melanoma.')],
 'An anatomical subtype can represent different molecular disease','**Uveal and cutaneous melanomas should not be treated as one uniform entity.**',['Molecular drivers and immune biology differ.','Selected systemic options also depend on factors such as HLA type and treatment eligibility.'],'**Use a uveal-melanoma-specific specialist pathway.**',['Assess hepatic and systemic spread appropriately.','Do not extrapolate a skin-melanoma drug indication without evidence.'],[['Uveal','GNAQ/GNA11 common'],['Cutaneous','Different common drivers'],['Metastatic pattern','Liver important']],[ref('NCI intraocular melanoma professional summary','https://www.cancer.gov/types/eye/hp/intraocular-melanoma-treatment-pdq')])

if __name__=='__main__':finalize('Oncology',3,'Solid Tumors in Internal Medicine','onco-solid',rows,40)
